    start = date.fromisoformat(period["start"])
    end = date.fromisoformat(period["end"])
    cutoff = datetime.fromisoformat(period["corrections_cutoff"].replace("Z", "+00:00")).timestamp()

    sites = {}
    with open(inp / "sites.csv", encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())
    employees = {}
    with open(inp / "employees.csv", encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            employees[r["employee_id"].strip()] = r["home_site"].strip()
    rates = {}
    with open(inp / "rates.csv", encoding="utf-8-sig", newline="") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Decimal(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site, id) -> [emp, dir, epoch]
    for site, (tz, fmt) in sites.items():
        d = inp / "exports" / site
        if not d.is_dir():
            continue
        for p in sorted(x for x in d.rglob("*") if x.is_file()):
            text = read_text(p)
            if fmt == "abbr-csv":
                rows = parse_abbr(text, tz)
            elif fmt == "epoch-jsonl":
                rows = parse_epoch(text)
            elif fmt == "offset-csv":
                rows = parse_offset(text)
            elif fmt == "legacy-fixed":
                rows = parse_legacy(text, tz)
            elif fmt == "de-tsv":
                rows = parse_de(text, tz)
            elif fmt == "local-csv":
                rows = parse_local_csv(text, tz)
            elif fmt == "local-jsonl":
                rows = parse_local_jsonl(text, tz)
            else:
                raise SystemExit(f"unknown format {fmt}")
