    existed = set(punches)
    corr = []
    cdir = inp / "corrections"
    if cdir.is_dir():
        for p in sorted(x for x in cdir.rglob("*") if x.is_file()):
            for r in csv.DictReader(io.StringIO(read_text(p))):
                if r.get("correction_id"):
                    corr.append({k: (v or "").strip() for k, v in r.items() if k})
