        return datetime.fromisoformat(r["issued_at"].replace("Z", "+00:00")).timestamp()
    corr = [r for r in corr if issued(r) <= cutoff]
    corr.sort(key=lambda r: (issued(r), r["correction_id"]))
    applied = 0
    for r in corr:
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                punches[key][2] = int(datetime.fromisoformat(r["time"]).timestamp())
                applied += 1
        elif act == "add":
            if key not in existed:
                punches[key] = [r["employee"], dir_norm(r["type"]),
                                int(datetime.fromisoformat(r["time"]).timestamp())]
                existed.add(key)
                applied += 1

