        shifts = []
        i = 0
        n = len(kept)
        pending = None
        for rts, dr, site in kept:
            if dr == "IN":
                if pending is not None:
                    if start <= wday(pending[0], hz) <= end:
                        exc["open_shifts"] += 1
                pending = (rts, site)
            else:
                if pending is not None and rts - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], rts, pending[1]))
                    pending = None
                else:
                    if pending is not None:
                        if start <= wday(pending[0], hz) <= end:
                            exc["open_shifts"] += 1
                        pending = None
                    if start <= wday(rts, hz) <= end:
                        exc["orphan_outs"] += 1
        if pending is not None and start <= wday(pending[0], hz) <= end:
            exc["open_shifts"] += 1

        # 6-8
        rows = []
        for a, b, site in shifts:
            wd = wday(a, hz)
            if start <= wd <= end:
                rows.append((a, b, site, wd))
        rows.sort()
        daily = {}
        weekly = {}
        tot = {"shifts": 0, "paid": 0, "ot": 0, "night": 0}
        gross = Decimal(0)
        for a, b, site, wd in rows:
            tz = sites[site][0]
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, tz), paid)
            used = daily.get(wd, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[wd] = used + paid
            wk = wd - timedelta(days=wd.weekday())
            reg_so_far = weekly.get(wk, 0)
            nd = paid - dot
            wot = max(0, reg_so_far + nd - 2400) - max(0, reg_so_far - 2400)
            weekly[wk] = reg_so_far + nd
            ot = dot + wot
            reg = paid - ot
            rate = Decimal(0)
            rl = rates.get(emp, [])
            for ef, rv in rl:
                if ef <= wd:
                    rate = rv
            if not rate and rl and all(ef > wd for ef, _ in rl):
                rate = rl[0][1]
            gross += rate * (Decimal(reg) + Decimal("1.5") * ot) / 60 + rate * Decimal("0.15") * night / 60
            tot["shifts"] += 1
            tot["paid"] += paid
            tot["ot"] += ot
            tot["night"] += night
        res[emp] = {"shifts": tot["shifts"], "paid_minutes": tot["paid"], "overtime_minutes": tot["ot"],
                    "night_minutes": tot["night"],
                    "gross": str(gross.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}

    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    g = Decimal(0)
    for v in res.values():
        for k in totals:
            totals[k] += v[k]
        g += Decimal(v["gross"])
    totals["gross"] = str(g.quantize(Decimal("0.01")))
    out = {"period": {"start": period["start"], "end": period["end"]}, "employees": res,
           "exceptions": exc, "totals": totals}
    Path(outp).write_text(json.dumps(out, indent=1))


def night_minutes(a, b, tz):
    if b <= a:
        return 0
    d0 = datetime.fromtimestamp(a, tz).date() - timedelta(days=1)
    d1 = datetime.fromtimestamp(b, tz).date()
    total = 0
    d = d0
    while d <= d1:
        s = int(datetime(d.year, d.month, d.day, 22, tzinfo=tz).timestamp())
        n = d + timedelta(days=1)
        e = int(datetime(n.year, n.month, n.day, 6, tzinfo=tz).timestamp())
        lo, hi = max(a, s), min(b, e)
        if hi > lo:
            total += hi - lo
        d += timedelta(days=1)
    return total // 60


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
